use std::env;
use std::io::{self, BufRead, Read, Write};
use std::process;

const SHORT_HELP: &str = "\
diffr 0.1.5
Nathan Moreau <nathan.moreau@m4x.org>

diffr adds word-level diff on top of unified diffs.
word-level diff information is displayed using text attributes.

USAGE:
    diffr reads from standard input and writes to standard output.

    Typical usage is for interactive use of diff:
    diff -u <file1> <file2> | diffr
    git show | diffr

OPTIONS:
        --colors <COLOR_SPEC>...    Configure color settings.
        --line-numbers              Display line numbers.
    -h, --help                      Prints help information
    -V, --version                   Prints version information
";

const LONG_HELP: &str = "\
diffr 0.1.5
Nathan Moreau <nathan.moreau@m4x.org>

diffr adds word-level diff on top of unified diffs.
word-level diff information is displayed using text attributes.

USAGE:
    diffr reads from standard input and writes to standard output.

    Typical usage is for interactive use of diff:
    diff -u <file1> <file2> | diffr
    git show | diffr

OPTIONS:
        --colors <COLOR_SPEC>...
            Configure color settings for console ouput.

            There are four faces to customize:
            +----------------+--------------+----------------+
            |  line prefix   |      +       |       -        |
            +----------------+--------------+----------------+
            | common segment |    added     |    removed     |
            | unique segment | refine-added | refine-removed |
            +----------------+--------------+----------------+

            The customization allows
            - to change the foreground or background color;
            - to set or unset the attributes 'bold', 'intense', 'underline';
            - to clear all attributes.

            Customization is done passing a color_spec argument.
            This flag may be provided multiple times.

            The syntax is the following:

            color_spec = face-name + ':' + attributes
            attributes = attribute
                       | attribute + ':' + attributes
            attribute  = ('foreground' | 'background') + ':' + color
                       | (<empty> | 'no') + font-flag
                       | 'none'
            font-flag  = 'italic'
                       | 'bold'
                       | 'intense'
                       | 'underline'
            color      = 'none'
                       | [0-255]
                       | [0-255] + ',' + [0-255] + ',' + [0-255]
                       | ('black', 'blue', 'green', 'red',
                          'cyan', 'magenta', 'yellow', 'white')

            For example, the color_spec

                'refine-added:background:blue:bold'

            sets the color of unique added segments with
            a blue background, written with a bold font.

        --line-numbers <compact|aligned>
            Display line numbers. Style is optional.
            When style = 'compact', take as little width as possible.
            When style = 'aligned', align to tab stops (useful if tab is used for indentation). [default: compact]

    -h, --help
            Prints help information

    -V, --version
            Prints version information
";

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum LineNumberStyle {
    Compact,
    Aligned,
    Fixed,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Color {
    None,
    Basic(u8),
    Ansi256(u8),
    Rgb(u8, u8, u8),
}

#[derive(Clone, Debug, PartialEq)]
pub struct Face {
    pub fg: Color,
    pub bg: Color,
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub intense: bool,
}

impl Face {
    pub fn new(fg: Color, bg: Color, bold: bool) -> Self {
        Self {
            fg,
            bg,
            bold,
            dimmed: false,
            italic: false,
            underline: false,
            intense: false,
        }
    }

    pub fn clear(&mut self) {
        self.fg = Color::None;
        self.bg = Color::None;
        self.bold = false;
        self.dimmed = false;
        self.italic = false;
        self.underline = false;
        self.intense = false;
    }

    pub fn ansi_escape(&self) -> String {
        let mut s = String::new();
        if self.bold {
            s.push_str("\x1b[1m");
        }
        if self.dimmed {
            s.push_str("\x1b[2m");
        }
        if self.italic {
            s.push_str("\x1b[3m");
        }
        if self.underline {
            s.push_str("\x1b[4m");
        }
        match &self.fg {
            Color::None => {}
            Color::Basic(c) => {
                if self.intense {
                    s.push_str(&format!("\x1b[38;5;{}m", c + 8));
                } else {
                    s.push_str(&format!("\x1b[{}m", 30 + c));
                }
            }
            Color::Ansi256(c) => {
                s.push_str(&format!("\x1b[38;5;{}m", c));
            }
            Color::Rgb(r, g, b) => {
                s.push_str(&format!("\x1b[38;2;{};{};{}m", r, g, b));
            }
        }
        match &self.bg {
            Color::None => {}
            Color::Basic(c) => {
                if self.intense {
                    s.push_str(&format!("\x1b[48;5;{}m", c + 8));
                } else {
                    s.push_str(&format!("\x1b[{}m", 40 + c));
                }
            }
            Color::Ansi256(c) => {
                s.push_str(&format!("\x1b[48;5;{}m", c));
            }
            Color::Rgb(r, g, b) => {
                s.push_str(&format!("\x1b[48;2;{};{};{}m", r, g, b));
            }
        }
        s
    }
}

pub struct Config {
    pub line_numbers: Option<LineNumberStyle>,
    pub added: Face,
    pub removed: Face,
    pub refine_added: Face,
    pub refine_removed: Face,
}

impl Config {
    pub fn default() -> Self {
        Self {
            line_numbers: None,
            added: Face::new(Color::Basic(2), Color::None, false),
            removed: Face::new(Color::Basic(1), Color::None, false),
            refine_added: Face::new(Color::Rgb(255, 255, 255), Color::Basic(2), true),
            refine_removed: Face::new(Color::Rgb(255, 255, 255), Color::Basic(1), true),
        }
    }
}

fn parse_color(s: &str) -> Result<Color, String> {
    if s == "none" {
        return Ok(Color::None);
    }
    match s {
        "black" => return Ok(Color::Basic(0)),
        "red" => return Ok(Color::Basic(1)),
        "green" => return Ok(Color::Basic(2)),
        "yellow" => return Ok(Color::Basic(3)),
        "blue" => return Ok(Color::Basic(4)),
        "magenta" => return Ok(Color::Basic(5)),
        "cyan" => return Ok(Color::Basic(6)),
        "white" => return Ok(Color::Basic(7)),
        _ => {}
    }
    if s.contains(',') {
        let parts: Vec<&str> = s.split(',').collect();
        if parts.len() == 3 {
            let parse_part = |p: &str| -> Option<u8> {
                if let Some(hex) = p.strip_prefix("0x").or_else(|| p.strip_prefix("0X")) {
                    u8::from_str_radix(hex, 16).ok()
                } else {
                    p.parse::<u8>().ok()
                }
            };
            if let (Some(r), Some(g), Some(b)) = (parse_part(parts[0]), parse_part(parts[1]), parse_part(parts[2])) {
                return Ok(Color::Rgb(r, g, b));
            }
        }
        return Err(format!(
            "unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'\n",
            s
        ));
    }
    if let Some(hex) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        if let Ok(v) = u8::from_str_radix(hex, 16) {
            return Ok(Color::Ansi256(v));
        } else {
            return Err(format!(
                "unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white\n",
                s
            ));
        }
    }
    if s.chars().all(|c| c.is_ascii_hexdigit()) {
        if let Ok(v) = s.parse::<u8>() {
            return Ok(Color::Ansi256(v));
        }
        if u64::from_str_radix(s, 16).is_ok() || s.parse::<u64>().is_ok() {
            return Err(format!(
                "unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'\n",
                s
            ));
        }
    }
    Err(format!(
        "unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white\n",
        s
    ))
}

fn apply_color_spec(config: &mut Config, spec: &str) -> Result<(), (String, i32)> {
    let parts: Vec<&str> = spec.split(':').collect();
    if parts.is_empty() {
        return Ok(());
    }
    let face_name = parts[0];
    let face = match face_name {
        "added" => &mut config.added,
        "refine-added" => &mut config.refine_added,
        "removed" => &mut config.removed,
        "refine-removed" => &mut config.refine_removed,
        _ => {
            return Err((
                format!(
                    "unexpected face name: got '{}', expected added|refine-added|removed|refine-removed\n",
                    face_name
                ),
                255,
            ));
        }
    };

    let mut i = 1;
    while i < parts.len() {
        let attr = parts[i];
        match attr {
            "none" => {
                face.clear();
            }
            "bold" => face.bold = true,
            "nobold" => face.bold = false,
            "dimmed" => face.dimmed = true,
            "nodimmed" => face.dimmed = false,
            "italic" => face.italic = true,
            "noitalic" => face.italic = false,
            "underline" => face.underline = true,
            "nounderline" => face.underline = false,
            "intense" => face.intense = true,
            "nointense" => face.intense = false,
            "foreground" => {
                i += 1;
                if i < parts.len() {
                    let c = parse_color(parts[i]).map_err(|e| (e, 255))?;
                    face.fg = c;
                } else {
                    return Err((
                        "unexpected color value: unrecognized color name ''. Choose from: black, blue, green, red, cyan, magenta, yellow, white\n".to_string(),
                        255,
                    ));
                }
            }
            "background" => {
                i += 1;
                if i < parts.len() {
                    let c = parse_color(parts[i]).map_err(|e| (e, 255))?;
                    face.bg = c;
                } else {
                    return Err((
                        "unexpected color value: unrecognized color name ''. Choose from: black, blue, green, red, cyan, magenta, yellow, white\n".to_string(),
                        255,
                    ));
                }
            }
            _ => {
                return Err((
                    format!(
                        "unexpected attribute name: got '{}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none\n",
                        attr
                    ),
                    255,
                ));
            }
        }
        i += 1;
    }
    Ok(())
}

fn parse_args() -> Result<Config, (String, i32)> {
    let args: Vec<String> = env::args().collect();
    let mut config = Config::default();
    let mut i = 1;

    while i < args.len() {
        let arg = &args[i];
        if arg == "-h" {
            print!("{}", SHORT_HELP);
            process::exit(0);
        } else if arg == "--help" {
            print!("{}", LONG_HELP);
            process::exit(0);
        } else if arg == "-V" || arg == "--version" {
            eprintln!("diffr 0.1.5");
            process::exit(0);
        } else if arg == "--line-numbers" {
            let mut style = LineNumberStyle::Compact;
            if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                i += 1;
                let val = &args[i];
                style = match val.as_str() {
                    "compact" => LineNumberStyle::Compact,
                    "aligned" => LineNumberStyle::Aligned,
                    "fixed" => LineNumberStyle::Fixed,
                    _ => {
                        return Err((
                            format!(
                                "unexpected line number style: got '{}', expected aligned|compact|fixed\n",
                                val
                            ),
                            255,
                        ));
                    }
                };
            }
            config.line_numbers = Some(style);
        } else if arg == "--colors" {
            if i + 1 < args.len() {
                i += 1;
                apply_color_spec(&mut config, &args[i])?;
            } else {
                return Err(("option requires an argument: '--colors'\n".to_string(), 2));
            }
        } else {
            return Err((
                format!("bad argument: '{}'\n{}", arg, SHORT_HELP),
                2,
            ));
        }
        i += 1;
    }

    Ok(config)
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Token {
    Word(String),
    Whitespace(String),
    Symbol(String),
    Newline,
}

fn tokenize_line(line: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let chars: Vec<char> = line.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c.is_alphanumeric() || c == '_' {
            let start = i;
            while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
                i += 1;
            }
            let word: String = chars[start..i].iter().collect();
            tokens.push(Token::Word(word));
        } else if c.is_whitespace() && c != '\n' {
            let start = i;
            while i < chars.len() && chars[i].is_whitespace() && chars[i] != '\n' {
                i += 1;
            }
            let ws: String = chars[start..i].iter().collect();
            tokens.push(Token::Whitespace(ws));
        } else {
            tokens.push(Token::Symbol(c.to_string()));
            i += 1;
        }
    }
    tokens
}

fn compute_lcs(a: &[Token], b: &[Token]) -> (Vec<bool>, Vec<bool>) {
    let m = a.len();
    let n = b.len();
    let mut dp = vec![vec![0u32; n + 1]; m + 1];

    for i in 1..=m {
        for j in 1..=n {
            if a[i - 1] == b[j - 1] {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = dp[i - 1][j].max(dp[i][j - 1]);
            }
        }
    }

    let mut a_common = vec![false; m];
    let mut b_common = vec![false; n];

    let mut i = m;
    let mut j = n;
    while i > 0 && j > 0 {
        if a[i - 1] == b[j - 1] {
            a_common[i - 1] = true;
            b_common[j - 1] = true;
            i -= 1;
            j -= 1;
        } else if dp[i - 1][j] >= dp[i][j - 1] {
            i -= 1;
        } else {
            j -= 1;
        }
    }

    (a_common, b_common)
}

struct TaggedToken {
    text: String,
    is_common: bool,
}

fn render_line(
    writer: &mut dyn Write,
    ln_str: Option<&str>,
    prefix: &str,
    prefix_face: &Face,
    tagged_tokens: &[TaggedToken],
    common_face: &Face,
    unique_face: &Face,
) -> io::Result<()> {
    write!(writer, "\x1b[0m")?;
    if let Some(ln) = ln_str {
        if prefix == " " {
            write!(writer, "{}", ln)?;
        } else {
            write!(writer, "{}{}\x1b[0m", prefix_face.ansi_escape(), ln)?;
        }
    }
    write!(writer, "{}{}\x1b[0m", prefix_face.ansi_escape(), prefix)?;

    if tagged_tokens.is_empty() {
        write!(writer, "\x1b[0m")?;
        return Ok(());
    }

    // Group adjacent tokens with same is_common tag
    let mut last_was_unique = false;
    let mut current_text = String::new();
    let mut current_common = tagged_tokens[0].is_common;

    for tok in tagged_tokens {
        if tok.is_common == current_common {
            current_text.push_str(&tok.text);
        } else {
            let face = if current_common { common_face } else { unique_face };
            write!(writer, "\x1b[0m{}{}\x1b[0m", face.ansi_escape(), current_text)?;
            if !current_common {
                last_was_unique = true;
            } else {
                last_was_unique = false;
            }
            current_text = tok.text.clone();
            current_common = tok.is_common;
        }
    }

    let face = if current_common { common_face } else { unique_face };
    write!(writer, "\x1b[0m{}{}\x1b[0m", face.ansi_escape(), current_text)?;
    if !current_common {
        last_was_unique = true;
    } else {
        last_was_unique = false;
    }

    if last_was_unique {
        write!(writer, "\x1b[0m{}\x1b[0m", common_face.ansi_escape())?;
    }

    Ok(())
}

fn parse_hunk_header(line: &str) -> Option<(usize, usize, usize, usize)> {
    if !line.starts_with("@@") {
        return None;
    }
    let rest = line.strip_prefix("@@")?.trim_start();
    let end_idx = rest.find("@@")?;
    let spec = &rest[..end_idx].trim();
    let mut parts = spec.split_whitespace();
    let old_part = parts.next()?;
    let new_part = parts.next()?;

    if !old_part.starts_with('-') || !new_part.starts_with('+') {
        return None;
    }

    let parse_range = |s: &str| -> Option<(usize, usize)> {
        if let Some(comma) = s.find(',') {
            let start = s[..comma].parse::<usize>().ok()?;
            let count = s[comma + 1..].parse::<usize>().ok()?;
            Some((start, count))
        } else {
            let start = s.parse::<usize>().ok()?;
            Some((start, 1))
        }
    };

    let (old_start, old_count) = parse_range(&old_part[1..])?;
    let (new_start, new_count) = parse_range(&new_part[1..])?;

    Some((old_start, old_count, new_start, new_count))
}

struct Block {
    old_lines: Vec<String>,
    new_lines: Vec<String>,
}

fn process_block(
    writer: &mut dyn Write,
    config: &Config,
    block: &Block,
    curr_old_ln: &mut usize,
    curr_new_ln: &mut usize,
    col_width_old: usize,
    col_width_new: usize,
    style_opt: Option<LineNumberStyle>,
) -> io::Result<()> {
    if block.old_lines.is_empty() && block.new_lines.is_empty() {
        return Ok(());
    }

    // Build old token stream
    let mut old_tokens = Vec::new();
    let mut old_line_token_counts = Vec::new();
    for (i, line) in block.old_lines.iter().enumerate() {
        if i > 0 {
            old_tokens.push(Token::Newline);
        }
        let toks = tokenize_line(line);
        old_line_token_counts.push(toks.len());
        old_tokens.extend(toks);
    }

    // Build new token stream
    let mut new_tokens = Vec::new();
    let mut new_line_token_counts = Vec::new();
    for (i, line) in block.new_lines.iter().enumerate() {
        if i > 0 {
            new_tokens.push(Token::Newline);
        }
        let toks = tokenize_line(line);
        new_line_token_counts.push(toks.len());
        new_tokens.extend(toks);
    }

    let (old_common, new_common) = compute_lcs(&old_tokens, &new_tokens);

    // Render old lines
    let mut tok_idx = 0;
    for (line_idx, line) in block.old_lines.iter().enumerate() {
        let count = old_line_token_counts[line_idx];
        let mut line_tagged = Vec::new();
        for _ in 0..count {
            let text = match &old_tokens[tok_idx] {
                Token::Word(w) => w.clone(),
                Token::Whitespace(ws) => ws.clone(),
                Token::Symbol(s) => s.clone(),
                Token::Newline => unreachable!(),
            };
            line_tagged.push(TaggedToken {
                text,
                is_common: old_common[tok_idx],
            });
            tok_idx += 1;
        }
        if line_idx + 1 < block.old_lines.len() {
            tok_idx += 1; // skip Newline token
        }

        let ln_str = if style_opt.is_some() {
            let s = format!("{:>width$}{}", curr_old_ln, " ".repeat(1 + col_width_new), width = col_width_old);
            let suffix = if style_opt == Some(LineNumberStyle::Aligned) { "\t" } else { "" };
            Some(format!("{}{}", s, suffix))
        } else {
            None
        };

        render_line(
            writer,
            ln_str.as_deref(),
            "-",
            &config.removed,
            &line_tagged,
            &config.removed,
            &config.refine_removed,
        )?;
        write!(writer, "\n")?;
        *curr_old_ln += 1;
    }

    // Render new lines
    let mut tok_idx = 0;
    for (line_idx, line) in block.new_lines.iter().enumerate() {
        let count = new_line_token_counts[line_idx];
        let mut line_tagged = Vec::new();
        for _ in 0..count {
            let text = match &new_tokens[tok_idx] {
                Token::Word(w) => w.clone(),
                Token::Whitespace(ws) => ws.clone(),
                Token::Symbol(s) => s.clone(),
                Token::Newline => unreachable!(),
            };
            line_tagged.push(TaggedToken {
                text,
                is_common: new_common[tok_idx],
            });
            tok_idx += 1;
        }
        if line_idx + 1 < block.new_lines.len() {
            tok_idx += 1; // skip Newline token
        }

        let ln_str = if style_opt.is_some() {
            let s = format!("{}{:>width$}", " ".repeat(col_width_old + 1), curr_new_ln, width = col_width_new);
            let suffix = if style_opt == Some(LineNumberStyle::Aligned) { "\t" } else { "" };
            Some(format!("{}{}", s, suffix))
        } else {
            None
        };

        render_line(
            writer,
            ln_str.as_deref(),
            "+",
            &config.added,
            &line_tagged,
            &config.added,
            &config.refine_added,
        )?;
        write!(writer, "\n")?;
        *curr_new_ln += 1;
    }

    Ok(())
}

fn main() {
    let config = match parse_args() {
        Ok(c) => c,
        Err((msg, code)) => {
            eprint!("{}", msg);
            process::exit(code);
        }
    };

    let stdin = io::stdin();
    let mut reader = stdin.lock();
    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());

    let mut raw_input = Vec::new();
    if let Err(_) = reader.read_to_end(&raw_input) {
        return;
    }

    if raw_input.is_empty() {
        return;
    }

    // Split input into lines preserving line endings / lack of trailing newline
    let mut lines = Vec::new();
    let mut start = 0;
    while start < raw_input.len() {
        if let Some(pos) = raw_input[start..].iter().position(|&b| b == b'\n') {
            lines.push((&raw_input[start..start + pos], true));
            start += pos + 1;
        } else {
            lines.push((&raw_input[start..], false));
            break;
        }
    }

    let mut line_idx = 0;
    while line_idx < lines.len() {
        let (line_bytes, has_newline) = lines[line_idx];
        let line_str = String::from_utf8_lossy(line_bytes).to_string();

        if let Some((old_start, old_count, new_start, new_count)) = parse_hunk_header(&line_str) {
            // Print hunk header
            write!(writer, "\x1b[0m{}\x1b[0m", line_str)?;
            if has_newline {
                write!(writer, "\n")?;
            }
            line_idx += 1;

            let max_old = if old_count > 0 { old_start + old_count - 1 } else { old_start };
            let max_new = if new_count > 0 { new_start + new_count - 1 } else { new_start };

            let w_old_max = max_old.to_string().len();
            let w_new_max = max_new.to_string().len();

            let col_width = match config.line_numbers {
                Some(LineNumberStyle::Fixed) => 3.max(w_old_max).max(w_new_max),
                Some(_) => 1.max(w_old_max).max(w_new_max),
                None => 0,
            };
            let total_width = col_width + 1 + col_width;

            let mut curr_old_ln = old_start;
            let mut curr_new_ln = new_start;

            let mut current_block = Block {
                old_lines: Vec::new(),
                new_lines: Vec::new(),
            };

            // Process lines inside hunk
            while line_idx < lines.len() {
                let (hunk_bytes, h_has_newline) = lines[line_idx];
                let hunk_str = String::from_utf8_lossy(hunk_bytes).to_string();

                if hunk_str.starts_with('-') {
                    if !current_block.new_lines.is_empty() {
                        process_block(
                            &mut writer,
                            &config,
                            &current_block,
                            &mut curr_old_ln,
                            &mut curr_new_ln,
                            col_width,
                            col_width,
                            config.line_numbers,
                        ).ok();
                        current_block.old_lines.clear();
                        current_block.new_lines.clear();
                    }
                    current_block.old_lines.push(hunk_str[1..].to_string());
                    line_idx += 1;
                } else if hunk_str.starts_with('+') {
                    current_block.new_lines.push(hunk_str[1..].to_string());
                    line_idx += 1;
                } else if hunk_str.starts_with(' ') {
                    process_block(
                        &mut writer,
                        &config,
                        &current_block,
                        &mut curr_old_ln,
                        &mut curr_new_ln,
                        col_width,
                        col_width,
                        config.line_numbers,
                    ).ok();
                    current_block.old_lines.clear();
                    current_block.new_lines.clear();

                    // Print context line
                    let content = &hunk_str[1..];
                    if config.line_numbers.is_some() {
                        let ln_str = if curr_old_ln == curr_new_ln {
                            format!("{:>width$}", curr_old_ln, width = total_width)
                        } else {
                            format!("{:>w1$} {:>w2$}", curr_old_ln, curr_new_ln, w1 = col_width, w2 = col_width)
                        };
                        let suffix = if config.line_numbers == Some(LineNumberStyle::Aligned) { "\t" } else { "" };
                        write!(writer, "{}{} {}", ln_str, suffix, content)?;
                    } else {
                        write!(writer, "\x1b[0m {}", content)?;
                    }
                    write!(writer, "\x1b[0m")?;
                    if h_has_newline {
                        write!(writer, "\n")?;
                    }
                    curr_old_ln += 1;
                    curr_new_ln += 1;
                    line_idx += 1;
                } else if hunk_str.starts_with('\\') {
                    process_block(
                        &mut writer,
                        &config,
                        &current_block,
                        &mut curr_old_ln,
                        &mut curr_new_ln,
                        col_width,
                        col_width,
                        config.line_numbers,
                    ).ok();
                    current_block.old_lines.clear();
                    current_block.new_lines.clear();

                    write!(writer, "\x1b[0m{}\x1b[0m", hunk_str)?;
                    if h_has_newline {
                        write!(writer, "\n")?;
                    }
                    line_idx += 1;
                } else {
                    // Non-hunk line inside hunk scope: flush block and break hunk loop
                    process_block(
                        &mut writer,
                        &config,
                        &current_block,
                        &mut curr_old_ln,
                        &mut curr_new_ln,
                        col_width,
                        col_width,
                        config.line_numbers,
                    ).ok();
                    current_block.old_lines.clear();
                    current_block.new_lines.clear();
                    break;
                }
            }

            // Flush remaining block at end of hunk
            process_block(
                &mut writer,
                &config,
                &current_block,
                &mut curr_old_ln,
                &mut curr_new_ln,
                col_width,
                col_width,
                config.line_numbers,
            ).ok();
        } else {
            // Non-hunk line
            write!(writer, "\x1b[0m{}\x1b[0m", line_str)?;
            if has_newline {
                write!(writer, "\n")?;
            }
            line_idx += 1;
        }
    }

    writer.flush().ok();
}
EOF"}

