    Basic(u8),
    Ansi256(u8),
    Rgb(u8, u8, u8),
}

#[derive(Clone, Debug, PartialEq)]
pub struct Face {
    pub fg: Color,
    pub bg: Color,
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub intense: bool,
}

impl Face {
    pub fn new(fg: Color, bg: Color, bold: bool) -> Self {
        Self {
            fg,
            bg,
            bold,
            dimmed: false,
            italic: false,
            underline: false,
            intense: false,
        }
    }

    pub fn clear(&mut self) {
        self.fg = Color::None;
        self.bg = Color::None;
        self.bold = false;
        self.dimmed = false;
        self.italic = false;
        self.underline = false;
        self.intense = false;
    }

    pub fn ansi_escape(&self) -> String {
        let mut s = String::new();
        if self.bold {
            s.push_str("\x1b[1m");
        }
        if self.dimmed {
            s.push_str("\x1b[2m");
        }
        if self.italic {
            s.push_str("\x1b[3m");
        }
        if self.underline {
            s.push_str("\x1b[4m");
