    pub bg: Color,
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub intense: bool,
}

impl Face {
    pub fn new(fg: Color, bg: Color, bold: bool) -> Self {
