            }

            process_block(
                &mut writer,
                &config,
                &current_block,
                &mut curr_old_ln,
                &mut curr_new_ln,
                col_width,
                col_width,
                config.line_numbers,
            ).ok();
        } else {
            write!(writer, "\x1b[0m")?;
            writer.write_all(line_bytes)?;
            write!(writer, "\x1b[0m")?;
            if has_newline {
                write!(writer, "\n")?;
            }
            line_idx += 1;
        }
    }

    writer.flush().ok();
    Ok(())
}
