                        };
                        let suffix = if style == LineNumberStyle::Aligned { "\t" } else { "" };
                        write!(writer, "{}{}\x1b[0m ", ln_str, suffix)?;
                        writer.write_all(content)?;
                    } else {
                        write!(writer, "\x1b[0m ")?;
                        writer.write_all(content)?;
                    }
                    write!(writer, "\x1b[0m")?;
                    if h_has_newline {
                        write!(writer, "\n")?;
                    }
                    curr_old_ln += 1;
                    curr_new_ln += 1;
                    line_idx += 1;
                } else if hunk_bytes.starts_with(b"\\") {
                    process_block(
                        &mut writer,
                        &config,
                        &current_block,
                        &mut curr_old_ln,
                        &mut curr_new_ln,
                        col_width,
                        col_width,
                        config.line_numbers,
                    ).ok();
                    current_block.old_lines.clear();
                    current_block.new_lines.clear();

                    write!(writer, "\x1b[0m")?;
                    writer.write_all(hunk_bytes)?;
                    write!(writer, "\x1b[0m")?;
                    if h_has_newline {
                        write!(writer, "\n")?;
                    }
                    line_idx += 1;
                } else {
                    process_block(
                        &mut writer,
                        &config,
                        &current_block,
                        &mut curr_old_ln,
                        &mut curr_new_ln,
                        col_width,
                        col_width,
                        config.line_numbers,
                    ).ok();
                    current_block.old_lines.clear();
                    current_block.new_lines.clear();
                    break;
                }
            }

            process_block(
                &mut writer,
                &config,
                &current_block,
                &mut curr_old_ln,
                &mut curr_new_ln,
                col_width,
                col_width,
                config.line_numbers,
            ).ok();
        } else {
            write!(writer, "\x1b[0m")?;
            writer.write_all(line_bytes)?;
            write!(writer, "\x1b[0m")?;
            if has_newline {
                write!(writer, "\n")?;
            }
            line_idx += 1;
        }
    }

    writer.flush().ok();
    Ok(())
}
