#[derive(Clone, Copy, Debug, PartialEq)]
pub enum LineNumberStyle {
    Compact,
    Aligned,
    Fixed,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Color {
    None,
    Basic(u8),
    Ansi256(u8),
    Rgb(u8, u8, u8),
}

#[derive(Clone, Debug, PartialEq)]
pub struct Face {
    pub fg: Color,
    pub bg: Color,
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub intense: bool,
}

impl Face {
    pub fn new(fg: Color, bg: Color, bold: bool) -> Self {
        Self {
            fg,
            bg,
            bold,
            dimmed: false,
            italic: false,
            underline: false,
            intense: false,
        }
    }

    pub fn clear(&mut self) {
        self.fg = Color::None;
        self.bg = Color::None;
        self.bold = false;
        self.dimmed = false;
        self.italic = false;
        self.underline = false;
        self.intense = false;
    }

    pub fn ansi_escape(&self) -> String {
        let mut s = String::new();
        if self.bold {
            s.push_str("\x1b[1m");
        }
        if self.dimmed {
            s.push_str("\x1b[2m");
        }
        if self.italic {
            s.push_str("\x1b[3m");
        }
        if self.underline {
            s.push_str("\x1b[4m");
        }
        match &self.fg {
            Color::None => {}
            Color::Basic(c) => {
                if self.intense {
                    s.push_str(&format!("\x1b[38;5;{}m", c + 8));
                } else {
                    s.push_str(&format!("\x1b[{}m", 30 + c));
                }
            }
            Color::Ansi256(c) => {
                s.push_str(&format!("\x1b[38;5;{}m", c));
            }
            Color::Rgb(r, g, b) => {
                s.push_str(&format!("\x1b[38;2;{};{};{}m", r, g, b));
            }
        }
        match &self.bg {
            Color::None => {}
            Color::Basic(c) => {
                if self.intense {
                    s.push_str(&format!("\x1b[48;5;{}m", c + 8));
                } else {
                    s.push_str(&format!("\x1b[{}m", 40 + c));
                }
            }
            Color::Ansi256(c) => {
                s.push_str(&format!("\x1b[48;5;{}m", c));
            }
            Color::Rgb(r, g, b) => {
                s.push_str(&format!("\x1b[48;2;{};{};{}m", r, g, b));
            }
        }
        s
    }
}

pub struct Config {
    pub line_numbers: Option<LineNumberStyle>,
