#[derive(Clone, Copy, Debug, PartialEq)]
pub enum LineNumberStyle {
    Compact,
    Aligned,
    Fixed,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Color {
    None,
    Basic(u8),
    Ansi256(u8),
    Rgb(u8, u8, u8),
}

#[derive(Clone, Debug, PartialEq)]
pub struct Face {
    pub fg: Color,
    pub bg: Color,
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub intense: bool,
}

impl Face {
    pub fn new(fg: Color, bg: Color, bold: bool) -> Self {
        Self {
            fg,
            bg,
            bold,
            dimmed: false,
            italic: false,
            underline: false,
            intense: false,
        }
    }

    pub fn clear(&mut self) {
        self.fg = Color::None;
        self.bg = Color::None;
        self.bold = false;
        self.dimmed = false;
        self.italic = false;
        self.underline = false;
        self.intense = false;
    }

    pub fn ansi_escape(&self) -> String {
        let mut s = String::new();
        if self.bold {
            s.push_str("\x1b[1m");
        }
        if self.dimmed {
            s.push_str("\x1b[2m");
        }
        if self.italic {
            s.push_str("\x1b[3m");
        }
        if self.underline {
            s.push_str("\x1b[4m");
        }
        match &self.fg {
            Color::None => {}
            Color::Basic(c) => {
                if self.intense {
                    s.push_str(&format!("\x1b[38;5;{}m", c + 8));
                } else {
                    s.push_str(&format!("\x1b[{}m", 30 + c));
                }
            }
            Color::Ansi256(c) => {
                s.push_str(&format!("\x1b[38;5;{}m", c));
            }
            Color::Rgb(r, g, b) => {
                s.push_str(&format!("\x1b[38;2;{};{};{}m", r, g, b));
            }
        }
        match &self.bg {
            Color::None => {}
            Color::Basic(c) => {
                if self.intense {
                    s.push_str(&format!("\x1b[48;5;{}m", c + 8));
                } else {
                    s.push_str(&format!("\x1b[{}m", 40 + c));
                }
            }
            Color::Ansi256(c) => {
                s.push_str(&format!("\x1b[48;5;{}m", c));
            }
            Color::Rgb(r, g, b) => {
                s.push_str(&format!("\x1b[48;2;{};{};{}m", r, g, b));
            }
        }
        s
    }
}

pub struct Config {
    pub line_numbers: Option<LineNumberStyle>,
    pub added: Face,
    pub removed: Face,
    pub refine_added: Face,
    pub refine_removed: Face,
}

impl Config {
    pub fn default() -> Self {
        Self {
            line_numbers: None,
            added: Face::new(Color::Basic(2), Color::None, false),
            removed: Face::new(Color::Basic(1), Color::None, false),
            refine_added: Face::new(Color::Rgb(255, 255, 255), Color::Basic(2), true),
            refine_removed: Face::new(Color::Rgb(255, 255, 255), Color::Basic(1), true),
        }
    }
}

fn parse_color(s: &str) -> Result<Color, String> {
    if s == "none" {
        return Ok(Color::None);
    }
    match s {
        "black" => return Ok(Color::Basic(0)),
        "red" => return Ok(Color::Basic(1)),
        "green" => return Ok(Color::Basic(2)),
        "yellow" => return Ok(Color::Basic(3)),
        "blue" => return Ok(Color::Basic(4)),
        "magenta" => return Ok(Color::Basic(5)),
        "cyan" => return Ok(Color::Basic(6)),
        "white" => return Ok(Color::Basic(7)),
        _ => {}
    }
    if s.contains(',') {
        let parts: Vec<&str> = s.split(',').collect();
        if parts.len() == 3 {
            let parse_part = |p: &str| -> Option<u8> {
                if let Some(hex) = p.strip_prefix("0x").or_else(|| p.strip_prefix("0X")) {
                    u8::from_str_radix(hex, 16).ok()
                } else {
                    p.parse::<u8>().ok()
                }
            };
            if let (Some(r), Some(g), Some(b)) = (parse_part(parts[0]), parse_part(parts[1]), parse_part(parts[2])) {
                return Ok(Color::Rgb(r, g, b));
            }
        }
        return Err(format!(
            "unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{}'\n",
            s
        ));
    }
    if let Some(hex) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        if let Ok(v) = u8::from_str_radix(hex, 16) {
            return Ok(Color::Ansi256(v));
        } else {
            return Err(format!(
                "unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white\n",
                s
            ));
        }
    }
    if s.chars().all(|c| c.is_ascii_hexdigit()) {
        if let Ok(v) = s.parse::<u8>() {
            return Ok(Color::Ansi256(v));
        }
        if u64::from_str_radix(s, 16).is_ok() || s.parse::<u64>().is_ok() {
            return Err(format!(
                "unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{}'\n",
                s
            ));
        }
    }
    Err(format!(
        "unexpected color value: unrecognized color name '{}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white\n",
        s
    ))
}

fn apply_color_spec(config: &mut Config, spec: &str) -> Result<(), (String, i32)> {
    let parts: Vec<&str> = spec.split(':').collect();
    if parts.is_empty() {
        return Ok(());
    }
    let face_name = parts[0];
    let face = match face_name {
        "added" => &mut config.added,
        "refine-added" => &mut config.refine_added,
        "removed" => &mut config.removed,
        "refine-removed" => &mut config.refine_removed,
        _ => {
            return Err((
                format!(
                    "unexpected face name: got '{}', expected added|refine-added|removed|refine-removed\n",
                    face_name
                ),
                255,
            ));
        }
    };

    let mut i = 1;
    while i < parts.len() {
        let attr = parts[i];
        match attr {
            "none" => {
                face.clear();
            }
            "bold" => face.bold = true,
            "nobold" => face.bold = false,
            "dimmed" => face.dimmed = true,
            "nodimmed" => face.dimmed = false,
            "italic" => face.italic = true,
            "noitalic" => face.italic = false,
            "underline" => face.underline = true,
            "nounderline" => face.underline = false,
            "intense" => face.intense = true,
            "nointense" => face.intense = false,
            "foreground" => {
                i += 1;
                if i < parts.len() {
                    let c = parse_color(parts[i]).map_err(|e| (e, 255))?;
                    face.fg = c;
                } else {
                    return Err((
                        "unexpected color value: unrecognized color name ''. Choose from: black, blue, green, red, cyan, magenta, yellow, white\n".to_string(),
                        255,
                    ));
                }
            }
            "background" => {
                i += 1;
                if i < parts.len() {
                    let c = parse_color(parts[i]).map_err(|e| (e, 255))?;
                    face.bg = c;
                } else {
                    return Err((
                        "unexpected color value: unrecognized color name ''. Choose from: black, blue, green, red, cyan, magenta, yellow, white\n".to_string(),
                        255,
                    ));
                }
            }
            _ => {
                return Err((
                    format!(
                        "unexpected attribute name: got '{}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none\n",
                        attr
                    ),
                    255,
                ));
            }
        }
        i += 1;
    }
    Ok(())
}

fn parse_args() -> Result<Config, (String, i32)> {
    let args: Vec<String> = env::args().collect();
    let mut config = Config::default();
    let mut i = 1;

    while i < args.len() {
        let arg = &args[i];
        if arg == "-h" {
            print!("{}", SHORT_HELP);
            process::exit(0);
        } else if arg == "--help" {
            print!("{}", LONG_HELP);
            process::exit(0);
        } else if arg == "-V" || arg == "--version" {
            eprintln!("diffr 0.1.5");
            process::exit(0);
        } else if arg == "--line-numbers" {
            let mut style = LineNumberStyle::Compact;
            if i + 1 < args.len() {
                let val = &args[i + 1];
                if val == "--help" {
                    print!("{}", LONG_HELP);
                    process::exit(0);
                }
                match val.as_str() {
                    "compact" => {
                        style = LineNumberStyle::Compact;
                        i += 1;
                    }
                    "aligned" => {
                        style = LineNumberStyle::Aligned;
                        i += 1;
                    }
                    "fixed" => {
                        style = LineNumberStyle::Fixed;
                        i += 1;
                    }
                    _ => {
                        return Err((
                            format!(
                                "unexpected line number style: got '{}', expected aligned|compact|fixed\n",
                                val
                            ),
                            255,
                        ));
                    }
                }
            }
            config.line_numbers = Some(style);
        } else if arg == "--colors" {
            if i + 1 < args.len() {
                i += 1;
                apply_color_spec(&mut config, &args[i])?;
            } else {
                return Err(("option requires an argument: '--colors'\n".to_string(), 2));
            }
        } else {
            return Err((
                format!("bad argument: '{}'\n{}", arg, SHORT_HELP),
                2,
            ));
        }
        i += 1;
    }

    Ok(config)
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Token {
    Word(Vec<u8>),
    Whitespace(Vec<u8>),
    Symbol(Vec<u8>),
    Newline,
}

fn tokenize_line(line: &[u8]) -> Vec<Token> {
    let mut tokens = Vec::new();
    let mut i = 0;
    while i < line.len() {
        let b = line[i];
        if b < 128 {
            if (b as char).is_alphanumeric() || b == b'_' {
                let start = i;
                while i < line.len() && (line[i] < 128 && ((line[i] as char).is_alphanumeric() || line[i] == b'_')) {
                    i += 1;
                }
                tokens.push(Token::Word(line[start..i].to_vec()));
            } else if (b as char).is_whitespace() && b != b'\n' {
                let start = i;
                while i < line.len() && (line[i] < 128 && (line[i] as char).is_whitespace() && line[i] != b'\n') {
                    i += 1;
                }
                tokens.push(Token::Whitespace(line[start..i].to_vec()));
            } else {
                tokens.push(Token::Symbol(vec![b]));
                i += 1;
            }
        } else {
            if let Ok(s) = std::str::from_utf8(&line[i..]) {
                if let Some(ch) = s.chars().next() {
                    let len = ch.len_utf8();
                    if ch.is_alphanumeric() {
                        let start = i;
                        let mut curr = i;
                        while curr < line.len() {
                            if let Ok(s_sub) = std::str::from_utf8(&line[curr..]) {
                                if let Some(c_sub) = s_sub.chars().next() {
                                    if c_sub.is_alphanumeric() || c_sub == '_' {
                                        curr += c_sub.len_utf8();
                                        continue;
                                    }
                                }
                            }
                            break;
                        }
                        tokens.push(Token::Word(line[start..curr].to_vec()));
                        i = curr;
                        continue;
                    } else if ch.is_whitespace() && ch != '\n' {
                        let start = i;
                        let mut curr = i;
                        while curr < line.len() {
                            if let Ok(s_sub) = std::str::from_utf8(&line[curr..]) {
                                if let Some(c_sub) = s_sub.chars().next() {
                                    if c_sub.is_whitespace() && c_sub != '\n' {
                                        curr += c_sub.len_utf8();
                                        continue;
                                    }
                                }
                            }
                            break;
                        }
                        tokens.push(Token::Whitespace(line[start..curr].to_vec()));
                        i = curr;
                        continue;
                    } else {
                        tokens.push(Token::Symbol(line[i..i + len].to_vec()));
                        i += len;
                        continue;
                    }
                }
            }
            tokens.push(Token::Symbol(vec![b]));
            i += 1;
        }
    }
    tokens
}

fn compute_lcs(a: &[Token], b: &[Token]) -> (Vec<bool>, Vec<bool>) {
    let m = a.len();
    let n = b.len();
    let mut dp = vec![vec![0u32; n + 1]; m + 1];

    for i in 1..=m {
        for j in 1..=n {
            if a[i - 1] == b[j - 1] {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = dp[i - 1][j].max(dp[i][j - 1]);
            }
        }
    }

    let mut a_common = vec![false; m];
    let mut b_common = vec![false; n];

    let mut i = m;
    let mut j = n;
    while i > 0 && j > 0 {
        if a[i - 1] == b[j - 1] {
            a_common[i - 1] = true;
            b_common[j - 1] = true;
            i -= 1;
            j -= 1;
        } else if dp[i - 1][j] >= dp[i][j - 1] {
            i -= 1;
        } else {
            j -= 1;
        }
    }

    (a_common, b_common)
}

struct TaggedToken {
    bytes: Vec<u8>,
    is_common: bool,
    is_whitespace: bool,
}

fn render_line(
    writer: &mut dyn Write,
    ln_info: Option<(&str, LineNumberStyle)>,
    prefix: &str,
    prefix_face: &Face,
    tagged_tokens: &[TaggedToken],
    common_face: &Face,
    unique_face: &Face,
    block_has_common: bool,
) -> io::Result<()> {
    if let Some((ln, style)) = ln_info {
        write!(writer, "\x1b[0m{}{}\x1b[0m", prefix_face.ansi_escape(), ln)?;
        if style == LineNumberStyle::Aligned {
            write!(writer, "\t")?;
        }
    }

    if tagged_tokens.is_empty() {
        write!(writer, "\x1b[0m{}{}\x1b[0m", prefix_face.ansi_escape(), prefix)?;
        return Ok(());
    }

    let rest_tokens;

    if tagged_tokens[0].is_whitespace {
        let mut prefix_str = prefix.as_bytes().to_vec();
        prefix_str.extend_from_slice(&tagged_tokens[0].bytes);
        write!(writer, "\x1b[0m{}{}\x1b[0m", prefix_face.ansi_escape(), String::from_utf8_lossy(&prefix_str))?;
        rest_tokens = &tagged_tokens[1..];
    } else {
        write!(writer, "\x1b[0m{}{}\x1b[0m", prefix_face.ansi_escape(), prefix)?;
        rest_tokens = &tagged_tokens[0..];
    }

    if rest_tokens.is_empty() {
        return Ok(());
    }

    let mut groups: Vec<(Vec<u8>, Face)> = Vec::new();
    let mut curr_bytes = Vec::new();
    let mut curr_common = rest_tokens[0].is_common;

    for tok in rest_tokens {
        if tok.is_common == curr_common {
            curr_bytes.extend_from_slice(&tok.bytes);
        } else {
            let face = if curr_common { common_face } else { unique_face };
            groups.push((curr_bytes.clone(), face.clone()));
            curr_bytes = tok.bytes.clone();
            curr_common = tok.is_common;
        }
    }
    if !curr_bytes.is_empty() {
        let face = if curr_common { common_face } else { unique_face };
        groups.push((curr_bytes, face.clone()));
    }

    let last_was_unique = !groups.is_empty() && groups.last().unwrap().1 == *unique_face;

    for (bytes, face) in groups {
        write!(writer, "\x1b[0m{}", face.ansi_escape())?;
        writer.write_all(&bytes)?;
        write!(writer, "\x1b[0m")?;
    }

    if last_was_unique && block_has_common {
        write!(writer, "\x1b[0m{}\x1b[0m", common_face.ansi_escape())?;
    }

    Ok(())
}

fn parse_hunk_header(line: &[u8]) -> Option<(usize, usize, usize, usize)> {
    let line_str = std::str::from_utf8(line).ok()?;
    if !line_str.starts_with("@@") {
        return None;
    }
    let rest = line_str.strip_prefix("@@")?.trim_start();
    let end_idx = rest.find("@@")?;
    let spec = &rest[..end_idx].trim();
    let mut parts = spec.split_whitespace();
    let old_part = parts.next()?;
    let new_part = parts.next()?;

    if !old_part.starts_with('-') || !new_part.starts_with('+') {
        return None;
    }

    let parse_range = |s: &str| -> Option<(usize, usize)> {
        if let Some(comma) = s.find(',') {
            let start = s[..comma].parse::<usize>().ok()?;
            let count = s[comma + 1..].parse::<usize>().ok()?;
            Some((start, count))
        } else {
            let start = s.parse::<usize>().ok()?;
            Some((start, 1))
        }
    };

    let (old_start, old_count) = parse_range(&old_part[1..])?;
    let (new_start, new_count) = parse_range(&new_part[1..])?;

    Some((old_start, old_count, new_start, new_count))
}

struct Block {
    old_lines: Vec<Vec<u8>>,
    new_lines: Vec<Vec<u8>>,
}

fn process_block(
    writer: &mut dyn Write,
    config: &Config,
    block: &Block,
    curr_old_ln: &mut usize,
    curr_new_ln: &mut usize,
    col_width_old: usize,
    col_width_new: usize,
    style_opt: Option<LineNumberStyle>,
) -> io::Result<()> {
    if block.old_lines.is_empty() && block.new_lines.is_empty() {
        return Ok(());
    }

    let mut old_tokens = Vec::new();
    let mut old_line_token_counts = Vec::new();
    for (i, line) in block.old_lines.iter().enumerate() {
        if i > 0 {
            old_tokens.push(Token::Newline);
        }
        let toks = tokenize_line(line);
        old_line_token_counts.push(toks.len());
        old_tokens.extend(toks);
    }

    let mut new_tokens = Vec::new();
    let mut new_line_token_counts = Vec::new();
    for (i, line) in block.new_lines.iter().enumerate() {
        if i > 0 {
            new_tokens.push(Token::Newline);
        }
        let toks = tokenize_line(line);
        new_line_token_counts.push(toks.len());
        new_tokens.extend(toks);
    }

    let (old_common, new_common) = compute_lcs(&old_tokens, &new_tokens);
    let block_has_common = old_common.iter().any(|&c| c) || new_common.iter().any(|&c| c);

    let mut tok_idx = 0;
    for (line_idx, _line) in block.old_lines.iter().enumerate() {
        let count = old_line_token_counts[line_idx];
        let mut line_tagged = Vec::new();
        for _ in 0..count {
            let (bytes, is_ws) = match &old_tokens[tok_idx] {
                Token::Word(w) => (w.clone(), false),
                Token::Whitespace(ws) => (ws.clone(), true),
                Token::Symbol(s) => (s.clone(), false),
                Token::Newline => unreachable!(),
            };
            line_tagged.push(TaggedToken {
                bytes,
                is_common: old_common[tok_idx],
                is_whitespace: is_ws,
            });
            tok_idx += 1;
        }
        if line_idx + 1 < block.old_lines.len() {
            tok_idx += 1;
        }

        let ln_info = if let Some(style) = style_opt {
            let s = format!("{:>width$}{}", curr_old_ln, " ".repeat(1 + col_width_new), width = col_width_old);
            Some((s, style))
        } else {
            None
        };

        render_line(
            writer,
            ln_info.as_ref().map(|(s, st)| (s.as_str(), *st)),
            "-",
            &config.removed,
            &line_tagged,
            &config.removed,
            &config.refine_removed,
            block_has_common,
        )?;
        write!(writer, "\n")?;
        *curr_old_ln += 1;
    }

    let mut tok_idx = 0;
    for (line_idx, _line) in block.new_lines.iter().enumerate() {
        let count = new_line_token_counts[line_idx];
        let mut line_tagged = Vec::new();
        for _ in 0..count {
            let (bytes, is_ws) = match &new_tokens[tok_idx] {
                Token::Word(w) => (w.clone(), false),
                Token::Whitespace(ws) => (ws.clone(), true),
                Token::Symbol(s) => (s.clone(), false),
                Token::Newline => unreachable!(),
            };
            line_tagged.push(TaggedToken {
                bytes,
                is_common: new_common[tok_idx],
                is_whitespace: is_ws,
            });
            tok_idx += 1;
        }
        if line_idx + 1 < block.new_lines.len() {
            tok_idx += 1;
        }

        let ln_info = if let Some(style) = style_opt {
            let s = format!("{}{:>width$}", " ".repeat(col_width_old + 1), curr_new_ln, width = col_width_new);
            Some((s, style))
        } else {
            None
        };

        render_line(
            writer,
            ln_info.as_ref().map(|(s, st)| (s.as_str(), *st)),
            "+",
            &config.added,
            &line_tagged,
            &config.added,
            &config.refine_added,
            block_has_common,
        )?;
        write!(writer, "\n")?;
        *curr_new_ln += 1;
    }

    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let config = match parse_args() {
        Ok(c) => c,
        Err((msg, code)) => {
            eprint!("{}", msg);
            process::exit(code);
        }
    };

    let stdin = io::stdin();
    let mut reader = stdin.lock();
    let stdout = io::stdout();
    let mut writer = io::BufWriter::new(stdout.lock());

    let mut raw_input = Vec::new();
    if reader.read_to_end(&mut raw_input).is_err() {
        return Ok(());
    }

    if raw_input.is_empty() {
        return Ok(());
    }

    let mut lines = Vec::new();
    let mut start = 0;
    while start < raw_input.len() {
        if let Some(pos) = raw_input[start..].iter().position(|&b| b == b'\n') {
            lines.push((&raw_input[start..start + pos], true));
            start += pos + 1;
        } else {
            lines.push((&raw_input[start..], false));
            break;
        }
    }

    let mut line_idx = 0;
    while line_idx < lines.len() {
        let (line_bytes, has_newline) = lines[line_idx];

        if let Some((old_start, old_count, new_start, new_count)) = parse_hunk_header(line_bytes) {
            write!(writer, "\x1b[0m")?;
            writer.write_all(line_bytes)?;
            write!(writer, "\x1b[0m")?;
            if has_newline {
                write!(writer, "\n")?;
            }
            line_idx += 1;

            let max_old = if old_count > 0 { old_start + old_count - 1 } else { old_start };
            let max_new = if new_count > 0 { new_start + new_count - 1 } else { new_start };

            let w_old_max = max_old.to_string().len();
            let w_new_max = max_new.to_string().len();

            let col_width = match config.line_numbers {
                Some(LineNumberStyle::Fixed) => 3.max(w_old_max).max(w_new_max),
                Some(_) => 1.max(w_old_max).max(w_new_max),
                None => 0,
            };
            let total_width = col_width + 1 + col_width;

            let mut curr_old_ln = old_start;
            let mut curr_new_ln = new_start;

            let mut current_block = Block {
                old_lines: Vec::new(),
                new_lines: Vec::new(),
            };

            while line_idx < lines.len() {
                let (hunk_bytes, h_has_newline) = lines[line_idx];

                if hunk_bytes.starts_with(b"-") {
                    if !current_block.new_lines.is_empty() {
                        process_block(
                            &mut writer,
                            &config,
                            &current_block,
                            &mut curr_old_ln,
                            &mut curr_new_ln,
                            col_width,
                            col_width,
                            config.line_numbers,
                        ).ok();
                        current_block.old_lines.clear();
                        current_block.new_lines.clear();
                    }
                    current_block.old_lines.push(hunk_bytes[1..].to_vec());
                    line_idx += 1;
                } else if hunk_bytes.starts_with(b"+") {
                    current_block.new_lines.push(hunk_bytes[1..].to_vec());
                    line_idx += 1;
                } else if hunk_bytes.starts_with(b" ") {
                    process_block(
                        &mut writer,
                        &config,
                        &current_block,
                        &mut curr_old_ln,
                        &mut curr_new_ln,
                        col_width,
                        col_width,
                        config.line_numbers,
                    ).ok();
                    current_block.old_lines.clear();
                    current_block.new_lines.clear();

                    let content = &hunk_bytes[1..];
                    if let Some(style) = config.line_numbers {
                        let ln_str = if curr_old_ln == curr_new_ln {
                            format!("{:>width$}", curr_old_ln, width = total_width)
                        } else {
                            format!("{:>w1$} {:>w2$}", curr_old_ln, curr_new_ln, w1 = col_width, w2 = col_width)
                        };
                        let suffix = if style == LineNumberStyle::Aligned { "\t" } else { "" };
                        write!(writer, "{}{}\x1b[0m ", ln_str, suffix)?;
                        writer.write_all(content)?;
                    } else {
                        write!(writer, "\x1b[0m ")?;
                        writer.write_all(content)?;
                    }
                    write!(writer, "\x1b[0m")?;
                    if h_has_newline {
                        write!(writer, "\n")?;
                    }
                    curr_old_ln += 1;
                    curr_new_ln += 1;
                    line_idx += 1;
                } else if hunk_bytes.starts_with(b"\\") {
                    process_block(
                        &mut writer,
                        &config,
                        &current_block,
                        &mut curr_old_ln,
                        &mut curr_new_ln,
                        col_width,
                        col_width,
                        config.line_numbers,
                    ).ok();
                    current_block.old_lines.clear();
                    current_block.new_lines.clear();

                    write!(writer, "\x1b[0m")?;
                    writer.write_all(hunk_bytes)?;
                    write!(writer, "\x1b[0m")?;
                    if h_has_newline {
                        write!(writer, "\n")?;
                    }
                    line_idx += 1;
                } else {
                    process_block(
                        &mut writer,
                        &config,
                        &current_block,
                        &mut curr_old_ln,
                        &mut curr_new_ln,
                        col_width,
                        col_width,
                        config.line_numbers,
                    ).ok();
                    current_block.old_lines.clear();
                    current_block.new_lines.clear();
                    break;
                }
            }

            process_block(
                &mut writer,
                &config,
                &current_block,
                &mut curr_old_ln,
                &mut curr_new_ln,
                col_width,
                col_width,
                config.line_numbers,
            ).ok();
        } else {
            write!(writer, "\x1b[0m")?;
            writer.write_all(line_bytes)?;
            write!(writer, "\x1b[0m")?;
            if has_newline {
                write!(writer, "\n")?;
            }
            line_idx += 1;
        }
    }

    writer.flush().ok();
    Ok(())
}
